const rawPrompt = String(args.prompt || '').trim();
if (!rawPrompt) throw new Error('需要 prompt');
const isVideo = kind === 'video' || kind === 'videoEdit';
const isMusic = kind === 'music';
const isImage = !isVideo && !isMusic;
const basePrompt = isMusic && !/^(?:创作|制作|生成|谱写|create|generate|compose|make)/i.test(rawPrompt) ? ('请用音乐生成工具直接创作一首音频作品：' + rawPrompt) : rawPrompt;
const prompt = isMusic && args.lyrics ? `${basePrompt}\n歌词：\n${String(args.lyrics).trim()}` : basePrompt;
const refImages = [].concat(args.images || args.image || []).filter(Boolean);

const mapImgRatio = (r) => {
  const s = String(r || '').trim();
  if (['1:1','9:16','3:4','4:3','16:9'].includes(s)) return s;
  const m = /^(\d+)\s*[xX×:]\s*(\d+)$/.exec(s);
  if (!m) return '';
  const v = +m[1] / +m[2];
  return v >= 1.55 ? '16:9' : v >= 1.15 ? '4:3' : v >= 0.88 ? '1:1' : v >= 0.68 ? '3:4' : '9:16';
};
const imgRatio = isImage ? mapImgRatio(args.ratio || args.size) : '';
const vidRatio = isVideo && args.ratio ? (/9:16|纵向|portrait|vertical/i.test(String(args.ratio)) ? '纵向 (9:16)' : '横向 (16:9)') : '';
const wantFormat = args.format && /gif/i.test(String(args.format)) ? 'GIF' : '';
const toolLabel = isMusic ? '制作音乐' : isVideo ? '制作视频' : '制作图片';

// 文生图与参考图改图（非 GIF）优先走宿主侧 content-push 直传 + 页内同源 StreamGenerate 异步直连：15~25 秒直出高清原图
if (isImage && wantFormat !== 'GIF') {
  const aspectHint = imgRatio ? `，${imgRatio} 画面比例` : '';
  const imgPrompt = /^(?:生成|画|绘制|制作|改|将|把|保持|create|generate|draw|make|edit|transform)/i.test(prompt)
    ? `${prompt}${aspectHint}`
    : `请生成一张高质量图片${aspectHint}：${prompt}`;
  const useTemp = args.temporary !== false;

  // 在宿主侧直接上传参考图到 content-push.googleapis.com（支持 CORS，免向 runPage 传 MB 级 base64 源码）
  const uploaded = [];
  for (let idx = 0; idx < refImages.length; idx++) {
    const v = refImages[idx];
    const s = typeof v === 'string' ? v : (v?.data || v?.url || '');
    if (!s) continue;
    let blob, mime = v?.mimeType || 'image/jpeg';
    if (/^https?:/.test(s)) {
      const r = await fetch(s);
      if (!r.ok) throw new Error('拉取参考图失败 HTTP ' + r.status);
      blob = await r.blob();
      mime = blob.type || mime;
    } else {
      const m = /^data:([^;]+);base64,(.+)$/.exec(s);
      if (m) mime = m[1];
      const b64 = m ? m[2] : s;
      const bin = atob(b64), u8 = new Uint8Array(bin.length);
      for (let j = 0; j < bin.length; j++) u8[j] = bin.charCodeAt(j);
      blob = new Blob([u8], { type: mime });
    }
    const ext = (mime.split('/')[1] || 'jpg').replace(/[^a-z0-9]/gi, '');
    const name = `ref_${idx}.${ext}`;
    const fd = new FormData();
    fd.append('file', blob, name);
    const ur = await fetch('https://content-push.googleapis.com/upload/', {
      method: 'POST', headers: { 'Push-ID': 'feeds/mcudyrk2a4khkz' }, body: fd,
    });
    if (!ur.ok) throw new Error('Gemini 参考图上传失败 HTTP ' + ur.status);
    const path = (await ur.text()).trim();
    if (!path) throw new Error('Gemini 参考图上传返回空路径');
    uploaded.push([[path, 1], name]);
  }

  return tools.openTab('https://gemini.google.com/app?hl=zh-CN', async tabId => {
    const jobId = 'gi_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    const started = await tools.runPage(tabId, `((jobId, imgPrompt, uploaded) => {
      const w = window.WIZ_global_data || {};
      const at = w.SNlM0e || '', bl = w.cfb2h || '', fsid = w.FdrFJe || '';
      if (!at) return { error: '未登录 Gemini（缺少会话令牌 SNlM0e）' };
      const jobs = window.__gemJobs || (window.__gemJobs = {});
      const state = jobs[jobId] = { done: false, urls: [], text: '', convId: '', error: null, at, bl, fsid };
      const reqId = Math.floor(Math.random() * 900000) + 100000;
      const url = 'https://gemini.google.com/_/BardChatUi/data/assistant.lamda.BardFrontendService/StreamGenerate?bl='
        + encodeURIComponent(bl) + '&f.sid=' + encodeURIComponent(fsid) + '&hl=zh-CN&_reqid=' + reqId + '&rt=c';
      const promptTuple = (uploaded && uploaded.length) ? [imgPrompt, 0, null, uploaded] : [imgPrompt];
      const inner = JSON.stringify([promptTuple, ['zh-CN'], ['', '', '']]);
      const body = new URLSearchParams({ 'f.req': JSON.stringify([null, inner]), at });
      const headers = {
        'content-type': 'application/x-www-form-urlencoded;charset=UTF-8',
        'x-same-domain': '1',
        'x-goog-ext-525001261-jspb': JSON.stringify([1, null, null, null, '56fdd199312815e2']),
      };
      const found = new Set();
      const walk = v => {
        if (typeof v === 'string') {
          if (v.includes('lh3.googleusercontent.com/gg')) found.add(v);
        } else if (Array.isArray(v)) {
          for (const x of v) walk(x);
        }
      };
      fetch(url, { method: 'POST', credentials: 'include', headers, body: body.toString() }).then(async resp => {
        if (!resp.ok) { state.error = 'HTTP ' + resp.status; state.done = true; return; }
        const txt = await resp.text();
        for (const line of txt.split(String.fromCharCode(10))) {
          if (!line.startsWith('[[')) continue;
          try {
            const arr = JSON.parse(line);
            for (const item of arr) {
              if (Array.isArray(item) && item[0] === 'wrb.fr' && typeof item[2] === 'string') {
                const obj = JSON.parse(item[2]);
                if (typeof obj?.[1]?.[0] === 'string' && obj[1][0]) state.convId = obj[1][0];
                const cand = obj?.[4]?.[0]?.[1]?.[0];
                if (typeof cand === 'string' && cand) state.text = cand;
                walk(obj);
              }
            }
          } catch {}
        }
        state.urls = [...found];
        state.done = true;
      }).catch(e => { state.error = e?.message || String(e); state.done = true; });
      return { ok: true };
    })(${JSON.stringify(jobId)}, ${JSON.stringify(imgPrompt)}, ${JSON.stringify(uploaded)})`, 10000, 'MAIN');
    if (started?.error) throw new Error(started.error);

    let finalSt = null, t0 = Date.now();
    while (Date.now() - t0 < 120000) {
      if (args.signal?.aborted) throw new Error('已取消');
      await tools.sleep(800);
      const st = await tools.runPage(tabId, `(() => {
        const s = window.__gemJobs?.[${JSON.stringify(jobId)}];
        return s ? { done: s.done, urls: s.urls, text: s.text, convId: s.convId, error: s.error } : null;
      })()`, 6000, 'MAIN').catch(() => null);
      if (st?.done) { finalSt = st; break; }
    }
    if (!finalSt) throw new Error('Gemini 生图超时，请稍后重试');
    if (finalSt.error) throw new Error('Gemini 生图失败: ' + finalSt.error);

    const rawUrl = finalSt.urls.find(u => u.includes('/gg-dl/')) || finalSt.urls[0];
    if (useTemp && finalSt.convId) {
      await tools.runPage(tabId, `(async (jobId) => {
        const s = window.__gemJobs?.[jobId];
        if (!s?.convId || !s.at) return;
        const u = 'https://gemini.google.com/_/BardChatUi/data/batchexecute?rpcids=GzXR5e&source-path=%2Fapp&bl='
          + encodeURIComponent(s.bl || '') + '&f.sid=' + encodeURIComponent(s.fsid || '') + '&hl=zh-CN&rt=c';
        await fetch(u, {
          method: 'POST', credentials: 'include',
          headers: { 'content-type': 'application/x-www-form-urlencoded;charset=UTF-8', 'x-same-domain': '1' },
          body: new URLSearchParams({ 'f.req': JSON.stringify([[['GzXR5e', JSON.stringify([s.convId]), null, 'generic']]]), at: s.at }).toString(),
        }).catch(() => {});
        delete window.__gemJobs[jobId];
      })(${JSON.stringify(jobId)})`, 8000, 'MAIN').catch(() => {});
    }
    if (!rawUrl) {
      const cleanTxt = String(finalSt.text || '').replace(/https?:\/\/googleusercontent\.com\/\S+/g, '').trim();
      throw new Error('Gemini 未生成图片' + (cleanTxt ? ': ' + cleanTxt.slice(0, 140) : ''));
    }
    const fullUrl = /=s\d+|=w\d+/.test(rawUrl) ? rawUrl : (rawUrl + '=s0');
    const dl = await tools.fetchMedia(fullUrl, 'image/png').catch(() => tools.fetchMedia(rawUrl, 'image/png')).catch(() => tools.blobFromTab(tabId, rawUrl, 'image/png'));
    if (!dl?.data) throw new Error('图片已生成但下载失败');
    return { mimeType: dl.mimeType || 'image/png', data: dl.data };
  }, { readyExpr: `window.WIZ_global_data && window.WIZ_global_data.SNlM0e`, signal: args.signal, timeout: 25000, world: 'MAIN' });
}

return tools.openTab('https://gemini.google.com/app?hl=zh-CN', async tabId => {
  const selRes = await tools.runPage(tabId, `(async (label, imgRatio, vidRatio, wantFormat) => {
    const sleep = ms => new Promise(r => setTimeout(r, ms));
    const vis = e => { const r = e.getBoundingClientRect(); return r.width > 1 && r.height > 1 && getComputedStyle(e).visibility !== 'hidden' && getComputedStyle(e).display !== 'none'; };
    const clean = s => String(s || '').replace(/\\s+/g, ' ').trim();
    const tbtn = document.querySelector('button[aria-label="上传和工具"],button[aria-label*="Upload"],button[aria-label*="工具"]');
    if (!tbtn) return { ok: false, err: '找不到上传和工具按钮' };
    tbtn.click();
    await sleep(500);
    const hit = [...document.querySelectorAll('gem-menu-item,[role="menuitemcheckbox"],[role="menuitem"]')].filter(vis).find(el => clean(el.innerText).includes(label));
    if (!hit) { document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true })); return { ok: false, err: '找不到工具: ' + label }; }
    hit.click();
    await sleep(700);
    const chipKey = label.replace(/^制作/, '');
    const hasChip = () => [...document.querySelectorAll('input-area-v2 button, .input-area-container button')].filter(vis).some(b => clean(b.innerText).includes(chipKey));
    if (!hasChip()) {
      tbtn.click(); await sleep(500);
      const hit2 = [...document.querySelectorAll('gem-menu-item,[role="menuitemcheckbox"],[role="menuitem"]')].filter(vis).find(el => clean(el.innerText).includes(label));
      if (hit2) { (hit2.querySelector('button') || hit2).click(); await sleep(700); }
    }
    if (!hasChip()) return { ok: false, err: '工具未激活: ' + label };
    const pickSub = async (btnMatch, optText) => {
      if (!optText) return;
      const b = [...document.querySelectorAll('button')].filter(vis).find(x => clean(x.innerText).includes(btnMatch) || (x.getAttribute('aria-label') || '').includes(btnMatch));
      if (!b) return;
      b.click();
      await sleep(420);
      const opt = [...document.querySelectorAll('.cdk-overlay-container button, .cdk-overlay-container [role="menuitem"], .cdk-overlay-container [role="menuitemradio"], .cdk-overlay-container gem-menu-item')].filter(vis).find(el => clean(el.innerText) === optText || clean(el.innerText).includes(optText));
      if (opt) { opt.click(); await sleep(320); }
      else document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    };
    if (imgRatio) await pickSub('宽高比', imgRatio);
    if (vidRatio) await pickSub('横向', vidRatio);
    if (wantFormat) await pickSub('格式', wantFormat);
    return { ok: true };
  })(${JSON.stringify(toolLabel)}, ${JSON.stringify(imgRatio)}, ${JSON.stringify(vidRatio)}, ${JSON.stringify(wantFormat)})`, 20000, 'MAIN');
  if (!selRes?.ok) throw new Error('Gemini 工具切换失败: ' + (selRes?.err || '未知'));

  if (refImages.length) {
    await tools.pasteImages(tabId, refImages, '.ql-editor[contenteditable="true"],[role="textbox"]', 'img[alt*="预览"],img[src^="blob:"],button[aria-label*="移除"],button[aria-label*="删除"]');
    await tools.sleep(1000);
  }
  await tools.fillEditor(tabId, prompt, {
    selector: '.ql-editor[contenteditable="true"],[role="textbox"]',
  });
  // Angular Material 的发送按钮在折叠后台标签里因 ng-animating / sendButtonVisibility 动画不触发 click，用 Enter (kHa -> FTa) 稳健提交
  await tools.runPage(tabId, `(async () => {
    const sleep = ms => new Promise(r => setTimeout(r, ms));
    for (let i = 0; i < 16; i++) {
      if (document.querySelector('gem-icon-button.send-button.has-input')) break;
      await sleep(150);
    }
    await sleep(250);
    const ed = document.querySelector('.ql-editor[contenteditable="true"],[role="textbox"]');
    if (!ed) return false;
    for (let k = 0; k < 3; k++) {
      ed.focus();
      ed.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true, cancelable: true }));
      await sleep(550);
      if (!(ed.innerText || '').trim()) return true;
    }
    const b = document.querySelector('button[aria-label="发送"],button[aria-label="Send message"]');
    if (b) b.click();
    return true;
  })()`, 12000, 'MAIN');

  const t0 = Date.now(), maxMs = isVideo ? 210000 : isMusic ? 150000 : 120000;
  let picked = null, lastText = '', errText = '', noMediaTicks = 0;
  while (Date.now() - t0 < maxMs) {
    if (args.signal?.aborted) throw new Error('已取消');
    await tools.sleep(isVideo || isMusic ? 2500 : 1500);
    const st = await tools.runPage(tabId, `((isImage) => {
      const clean = s => String(s || '').replace(/\\s+/g, ' ').trim();
      const stopBtn = !!document.querySelector('button[aria-label*="停止"],button[aria-label*="Stop"]');
      const resps = [...document.querySelectorAll('model-response')];
      const last = resps[resps.length - 1];
      if (!last) return { stopBtn, ready: false };
      const text = clean(last.innerText || '').slice(0, 600);
      const hasDownload = !!last.querySelector('button[aria-label="下载完整尺寸的图片"],button[aria-label="下载音乐作品"],button[aria-label*="下载"],button[aria-label*="Download"]');
      const hasFeedback = hasDownload || !!last.querySelector('button[aria-label="答得好"],button[aria-label="Good response"]');
      const hasMediaSlot = hasDownload || !!last.querySelector('generated-image,single-image,img.image,video,audio');
      if (isImage) {
        const imgs = [...last.querySelectorAll('img')].map(i => ({
          src: i.currentSrc || i.src || '', w: i.naturalWidth || 0, h: i.naturalHeight || 0, complete: i.complete,
        })).filter(x => x.src && x.complete && Math.max(x.w, x.h) >= 256 && !/sparkle|avatar|ogw|ACg8/i.test(x.src))
          .sort((a, b) => (b.w * b.h) - (a.w * a.h));
        return { stopBtn, hasFeedback, hasDownload, hasMediaSlot, text, media: imgs[0] ? { type: 'image', src: imgs[0].src, w: imgs[0].w, h: imgs[0].h } : null };
      }
      const vids = [...last.querySelectorAll('video, video source, audio, audio source')].map(v => ({
        src: v.currentSrc || v.src || '', tag: v.tagName.toLowerCase()
      })).filter(x => x.src && (x.src.startsWith('http') || x.src.startsWith('blob:') || x.src.startsWith('data:')));
      return { stopBtn, hasFeedback, hasDownload, hasMediaSlot, text, media: vids[0] ? { type: 'video', src: vids[0].src } : null };
    })(${JSON.stringify(isImage)})`, 12000, 'MAIN').catch(() => null);
    if (!st) continue;
    if (st.text) lastText = st.text;
    if (st.media?.src && (!st.stopBtn || st.hasFeedback)) { picked = st.media; break; }
    const bodyOnly = String(st.text || '').replace(/^(?:Gemini\s*(?:说|said)[:：]?\s*)+/i, '').trim();
    if (!st.stopBtn && st.hasFeedback && !st.media && !st.hasMediaSlot && bodyOnly.length > 6 && Date.now() - t0 > 15000) {
      if ((++noMediaTicks) >= 4) { errText = bodyOnly; break; }
    } else {
      noMediaTicks = 0;
    }
  }
  if (!picked?.src) {
    throw new Error('Gemini 未生成目标媒体' + (errText || lastText ? ': ' + (errText || lastText).slice(0, 220) : '（超时）'));
  }
  const fallbackMime = isImage ? (wantFormat === 'GIF' ? 'image/gif' : 'image/png') : 'video/mp4';
  if (picked.src.startsWith('http')) {
    return tools.fetchMedia(picked.src, fallbackMime).catch(() => tools.blobFromTab(tabId, picked.src, fallbackMime));
  }
  return tools.blobFromTab(tabId, picked.src, fallbackMime);
}, { readyExpr: `document.querySelector('[data-test-id="bard-mode-menu-button"]') && document.querySelector('.ql-editor,[role="textbox"]')`, signal: args.signal, timeout: 25000, world: 'MAIN' });

chatCode:
const msgs = Array.isArray(args.messages) ? args.messages : [];
const sys = msgs.filter(m => m.role === 'system').map(m => tools.textOf(m.content)).filter(Boolean).join('\n');
const hist = msgs.filter(m => m.role !== 'system');
const last = hist[hist.length - 1];
const prompt = (sys ? `[System]\n${sys}\n\n` : '') + (hist.length > 1
  ? hist.map(m => `${m.role === 'assistant' ? 'Assistant' : 'User'}: ${tools.textOf(m.content)}`).join('\n\n')
  : tools.textOf(last?.content || args.prompt || ''));
if (!prompt.trim()) throw new Error('对话内容为空');
const imgs = Array.isArray(last?.content) ? last.content.filter(p => p && p.type === 'image' && (p.data || p.url)) : [];
const m = String(args.model || '').toLowerCase();
const modeKey = /neon/.test(m) ? 'neon' : /auto/.test(m) ? 'auto' : 'hydrogen';
const MODE_IDS = { auto: '8c46e95b1a07cecc', hydrogen: '56fdd199312815e2', neon: 'e6fa609c3fa255c0' };
const modeId = MODE_IDS[modeKey] || MODE_IDS.hydrogen;
const useTemp = args.temporary !== false;
const gemId = String(args.gemId || '').trim();
const acct = args.account ?? args.authuser ?? args.u;
const isIdx = acct !== undefined && acct !== null && /^\d+$/.test(String(acct).trim());
const uPrefix = isIdx ? '/u/' + String(acct).trim() : '';
const wantEmail = acct && !isIdx && String(acct).includes('@') ? String(acct).trim().toLowerCase() : '';
const baseRoute = gemId ? ('/gem/' + encodeURIComponent(gemId)) : '/app';
const targetUrl = 'https://gemini.google.com' + uPrefix + baseRoute + '?hl=zh-CN' + (wantEmail ? '&authuser=' + encodeURIComponent(wantEmail) : '');
const cleanText = t => String(t || '').replace(/https?:\/\/googleusercontent\.com\/lmdx_content\/\S+/gi, '').replace(/\n{3,}/g, '\n\n').trim();
const ED_SEL = 'rich-textarea div.ql-editor,.ql-editor[contenteditable="true"],[role="textbox"]';

return tools.openTab(targetUrl, async tabId => {
  if (wantEmail) {
    const actual = await tools.runPage(tabId, `(window.WIZ_global_data?.oPEP7c || document.querySelector('a[aria-label*="Google 账号"],a[aria-label*="Google Account"]')?.getAttribute('aria-label') || '').toLowerCase()`, 6000, 'MAIN').catch(() => '');
    if (actual && !actual.includes(wantEmail)) throw new Error('目标账号不匹配: 期望 ' + wantEmail + '，当前页为 ' + actual);
  }

  // 纯文本且非指定 Gem：优先走原生同源 StreamGenerate 异步真流式
  if (!imgs.length && !gemId) {
    const jobId = 'g_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    const started = await tools.runPage(tabId, `((jobId, prompt, modeId, uPrefix) => {
      const w = window.WIZ_global_data || {};
      const at = w.SNlM0e || '', bl = w.cfb2h || '', fsid = w.FdrFJe || '';
      if (!at) return { error: '未登录 Gemini（缺少会话令牌 SNlM0e）' };
      const jobs = window.__gemJobs || (window.__gemJobs = {});
      const state = jobs[jobId] = { done: false, text: '', thought: '', convId: '', error: null, at, bl, fsid };
      const reqId = Math.floor(Math.random() * 900000) + 100000;
      const url = 'https://gemini.google.com' + (uPrefix || '') + '/_/BardChatUi/data/assistant.lamda.BardFrontendService/StreamGenerate?bl='
        + encodeURIComponent(bl) + '&f.sid=' + encodeURIComponent(fsid) + '&hl=zh-CN&_reqid=' + reqId + '&rt=c';
      const inner = JSON.stringify([[prompt], ['zh-CN'], ['', '', '']]);
      const body = new URLSearchParams({ 'f.req': JSON.stringify([null, inner]), at });
      const headers = {
        'content-type': 'application/x-www-form-urlencoded;charset=UTF-8',
        'x-same-domain': '1',
        'x-goog-ext-525001261-jspb': JSON.stringify([1, null, null, null, modeId]),
      };
      const parseLines = buf => {
        for (const line of buf.split(String.fromCharCode(10))) {
          if (!line.startsWith('[[')) continue;
          try {
            const arr = JSON.parse(line);
            for (const item of arr) {
              if (Array.isArray(item) && item[0] === 'wrb.fr' && typeof item[2] === 'string') {
                const obj = JSON.parse(item[2]);
                if (typeof obj?.[1]?.[0] === 'string' && obj[1][0]) state.convId = obj[1][0];
                const cand = obj?.[4]?.[0]?.[1]?.[0];
                if (typeof cand === 'string' && cand) state.text = cand;
                const th = obj?.[4]?.[0]?.[37]?.[0]?.[0];
                if (typeof th === 'string' && th) state.thought = th;
              }
            }
          } catch {}
        }
      };
      (async () => {
        try {
          const resp = await fetch(url, { method: 'POST', credentials: 'include', headers, body: body.toString() });
          if (!resp.ok) { state.error = 'HTTP ' + resp.status; state.done = true; return; }
          if (resp.body && resp.body.getReader) {
            const rd = resp.body.getReader(), dec = new TextDecoder();
            let carry = '';
            while (true) {
              const { value, done } = await rd.read();
              if (done) break;
              carry += dec.decode(value, { stream: true });
              const nl = carry.lastIndexOf(String.fromCharCode(10));
              if (nl >= 0) { parseLines(carry.slice(0, nl)); carry = carry.slice(nl + 1); }
            }
            if (carry) parseLines(carry);
          } else {
            parseLines(await resp.text());
          }
          state.done = true;
        } catch (e) {
          state.error = e?.message || String(e);
          state.done = true;
        }
      })();
      return { ok: true };
    })(${JSON.stringify(jobId)}, ${JSON.stringify(prompt)}, ${JSON.stringify(modeId)}, ${JSON.stringify(uPrefix)})`, 8000, 'MAIN');
    if (started?.error) throw new Error(started.error);

    let emitted = '', finalSt = null, t0 = Date.now();
    const maxMs = modeKey === 'neon' ? 240000 : 150000;
    while (Date.now() - t0 < maxMs) {
