    while (Date.now() < planDeadline) {
      if (args.signal?.aborted) throw new Error('已取消');
      await tools.sleep(1500);
      const st = await tools.runPage(tabId, `(() => {
        const vis = e => { const r = e.getBoundingClientRect(); return r.width > 1 && r.height > 1; };
        const btn = [...document.querySelectorAll('button')].filter(vis).find(b => /开始研究|Start\s*research/i.test((b.innerText || b.getAttribute('aria-label') || '').trim()));
        if (btn && !btn.disabled) { btn.click(); return { clicked: true }; }
        const running = /正在研究|Researching|Searching\s+websites|正在搜索/i.test(document.body?.innerText || '');
        return { clicked: false, running };
      })()`, 8000, 'MAIN').catch(() => ({}));
      if (st?.clicked || st?.running) { startedResearch = true; break; }
    }
    if (!startedResearch) throw new Error('未检测到 Deep Research 研究计划确认按钮');

    // 4) 等待研究报告完成，抓取完整正文与引用链接
    let report = '', sources = [], chatUrl = '', prev = '', stable = 0;
    const reportDeadline = Date.now() + maxMs;
    while (Date.now() < reportDeadline) {
      if (args.signal?.aborted) throw new Error('已取消');
      await tools.sleep(3000);
      const st = await tools.runPage(tabId, `(() => {
        const stopBtn = !!document.querySelector('button[aria-label*="停止"],button[aria-label*="Stop"],gem-icon-button.stop');
        const exportBtn = !![...document.querySelectorAll('button')].find(b => /导出|Export|分享并导出|Google\s*Docs/i.test((b.innerText || b.getAttribute('aria-label') || '').trim()));
        const panel = document.querySelector('immersive-panel,deep-research-immersive-panel,extended-response-panel') || [...document.querySelectorAll('model-response')].slice(-1)[0];
        const txt = (panel?.innerText || '').trim();
        const links = [...(panel || document).querySelectorAll('a[href^="http"]')].map(a => ({ title: (a.innerText || '').trim().slice(0, 80), url: a.href })).filter(x => !/google\.com\/(?:policies|intl|support)/i.test(x.url));
        return { stopBtn, exportBtn, txt, links: links.slice(0, 40), url: location.href };
      })()`, 10000, 'MAIN').catch(() => null);
      if (!st) continue;
      chatUrl = st.url || chatUrl;
      if (st.links?.length) sources = st.links;
      if (st.txt && st.txt.length > 200 && !st.stopBtn) {
        if (st.exportBtn && st.txt === prev) { report = st.txt; break; }
        if (st.txt === prev) { if (++stable >= 3) { report = st.txt; break; } }
        else { stable = 0; prev = st.txt; }
      } else { stable = 0; if (st.txt) prev = st.txt; }
    }
    report = (report || prev).replace(/https?:\/\/googleusercontent\.com\/lmdx_content\/\S+/gi, '').trim();
    if (!report) throw new Error('Deep Research 超时未产出完整报告，可在 chatUrl 查看进度: ' + chatUrl);
    return { report, sources, chatUrl };
  }, { readyExpr: READY_APP, signal: args.signal, timeout: 30000, world: 'MAIN' });
}

